// Shared types for the QuotaDock Codex provider (Phase 1B).
//
// Field names that mirror the app-server protocol follow the schema generated by
// `codex app-server generate-json-schema` from codex-cli 0.162.0-alpha.2.

/** The codex-cli version this provider was verified against on this machine. */
export const VERIFIED_CODEX_VERSION = "0.162.0-alpha.2";

/**
 * The only JSON-RPC requests QuotaDock is allowed to send. The app-server also exposes
 * powerful methods (fs/writeFile, process/spawn, account/logout,
 * account/rateLimitResetCredit/consume, ...); they are refused before reaching the wire.
 */
export const READ_ONLY_REQUEST_METHODS: ReadonlySet<string> = new Set([
  "initialize",
  "account/read",
  "account/rateLimits/read",
]);

/** The only client notification QuotaDock sends (part of the initialize handshake). */
export const CLIENT_NOTIFICATION_METHODS: ReadonlySet<string> = new Set(["initialized"]);

// ---------------------------------------------------------------------------
// Discovery
// ---------------------------------------------------------------------------

export type CodexInstallationSource = "desktop" | "standalone" | "vscode" | "manual" | "unknown";

export interface CodexInstallation {
  path: string;
  /** Parsed from `codex --version`, e.g. "0.162.0-alpha.2". */
  version: string;
  source: CodexInstallationSource;
  /** Human-readable note on where this copy came from. */
  detail?: string;
}

/**
 * - verified: exactly the version this provider was tested against.
 * - unverified-newer: newer than the verified version; probably compatible, not proven.
 * - unsupported-older: older than the verified version; not used unless explicitly allowed.
 * - unparseable: `--version` output could not be parsed.
 */
export type VersionGate = "verified" | "unverified-newer" | "unsupported-older" | "unparseable";

export interface DaemonStatus {
  /** The CLI has the `app-server daemon` subcommand. */
  available: boolean;
  /** A managed daemon answered on its control socket. */
  running: boolean;
  version?: string;
  backend?: string;
  /** Sanitized output of `codex app-server daemon version` when it succeeded. */
  raw?: unknown;
  /** First line of the failure, sanitized. */
  error?: string;
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

export type TransportKind = "daemon-proxy" | "stdio-app-server";

/** Result of the `initialize` request (schema: v1/InitializeResponse). */
export interface InitializeResult {
  userAgent: string;
  codexHome: string;
  platformFamily: string;
  platformOs: string;
}

// ---------------------------------------------------------------------------
// Quota data
// ---------------------------------------------------------------------------

export interface QuotaWindow {
  /** Exactly as reported by the backend; never rewritten. */
  usedPercent: number | null;
  /** 100 - usedPercent, clamped to [0, 100]; null when usedPercent is null. */
  remainingPercent: number | null;
  windowDurationMins: number | null;
  /** Backend-supplied timestamp, kept verbatim (observed to be Unix seconds). */
  resetsAt: number | null;
  /** resetsAt rendered as ISO-8601, or null when resetsAt is null or implausible. */
  resetsAtIso: string | null;
}

export interface RateLimitBucket {
  limitId: string;
  primary: QuotaWindow | null;
  secondary: QuotaWindow | null;
  raw: unknown;
}

export type WindowClass = "five-hour" | "weekly" | "unknown";

export type UsageAvailability = "allowed" | "blocked" | "unknown";

export interface CodexQuotaSnapshot {
  provider: "codex";
  capturedAt: string;
  codexCliVersion: string | null;
  transport: TransportKind;

  /** Authoritative availability signal from the backend. Never inferred from resetsAt. */
  ordinaryUsageAllowed: boolean | null;
  availability: UsageAvailability;

  fiveHour: QuotaWindow | null;
  weekly: QuotaWindow | null;
  /** Which bucket fiveHour/weekly were derived from. */
  sourceBucket: "codex" | "legacy" | null;

  /** Every bucket from rateLimitsByLimitId, unknown ones included. Empty when the field is absent. */
  buckets: Record<string, RateLimitBucket>;

  resetCredits: { availableCount: number | null } | null;

  accountId: string | null;

  /** Non-fatal parser/normalizer findings (duplicate windows, missing buckets, ...). */
  warnings: string[];

  raw?: unknown;
}

// ---------------------------------------------------------------------------
// Provider results
// ---------------------------------------------------------------------------

export type CodexReadResult =
  | { status: "ok"; snapshot: CodexQuotaSnapshot }
  | { status: "not-authenticated"; message: string }
  | { status: "unsupported-auth"; message: string; authType: string }
  | { status: "no-installation"; message: string }
  | { status: "unsupported-version"; message: string; installation: CodexInstallation; gate: VersionGate }
  | { status: "error"; errorKind: "transport" | "rpc" | "timeout" | "parse"; message: string; code?: number };

// ---------------------------------------------------------------------------
// Transitions (Phase 1B: detection only, no classification)
// ---------------------------------------------------------------------------

export interface QuotaTransitionChange {
  bucket: string;
  slot: "primary" | "secondary" | "bucket";
  field: "usedPercent" | "resetsAt" | "windowDurationMins" | "presence";
  from: unknown;
  to: unknown;
}

export interface QuotaTransition {
  percentageChanged: boolean;
  resetTimestampChanged: boolean;
  bucketTopologyChanged: boolean;
  /** Some usedPercent went down. A candidate only: the cause is not classified here. */
  resetCandidate: boolean;
  changes: QuotaTransitionChange[];
}

export interface Logger {
  info(message: string): void;
  warn(message: string): void;
  debug(message: string): void;
}

export const silentLogger: Logger = { info() {}, warn() {}, debug() {} };
